const compiledTemplates = [...sourceTemplates]
  .sort((a, b) => b[0].replace(/\{[^}]+\}/g, "").length - a[0].replace(/\{[^}]+\}/g, "").length)
  .map(([source, russian, italian]) => {
    const keys: string[] = [];
    const pattern = source.split(/(\{(?:value|detail|name)\})/).map((part) => {
      if (/^\{(?:value|detail|name)\}$/.test(part)) {
        keys.push(part);
        return "(.+?)";
      }
      return part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    }).join("");
    return { pattern: new RegExp(`^${pattern}$`, "s"), keys, russian, italian };
  });

